/**
 * Deletes a directory and all sub-directories.
 * @param directory the directory to delete, must not be {@code null}
 * @throws IOException in case deletion is unsuccessful
 */
private static void deleteDirectory(File directory) throws IOException {
    if (!directory.isDirectory()) {
        throw new IOException("Provided file is not a directory");
    }
    File[] files = directory.listFiles();
    if (files == null) {
        throw new IOException("Could not list files in directory");
    }
    for (File file : files) {
        if (file.isDirectory()) {
            deleteDirectory(file);
        } else {
            deleteFile(file);
        }
    }
    directory.delete();
}

