private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
  if (graph == null || vertices == null || vertices.isEmpty()) {
    return false;
  }

  Set<V> remainingVertices = new HashSet<>(vertices);
  while (!remainingVertices.isEmpty()) {
    V vertex = remainingVertices.iterator().next();
    remainingVertices.remove(vertex);
    for (V otherVertex : remainingVertices) {
      if (!graph.hasEdgeBetween(vertex, otherVertex)) {
        return false;
      }
    }
  }

  return true;
}
