public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
  Objects.requireNonNull(file, "file must not be null");
  Objects.requireNonNull(timeRanges, "timeRanges must not be null");

  List<ThreadSnapshot> snapshots = new ArrayList<>();

  try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
    String line;
    while ((line = reader.readLine()) != null) {
      ThreadSnapshot snapshot = parseThreadSnapshot(line);
      if (snapshot != null && isIn TimeRange(snapshot, timeRanges)) {
        snapshots.add(snapshot);
      }
    }
  } catch (FileNotFoundException e) {
    throw new IOException("Error reading file", e);
  }

  return snapshots;
}

/**
 * Parse a thread snapshot from a string
 *
 * @param snapshot the snapshot string
 * @return the parsed thread snapshot
 * @throws IllegalArgumentException if the string is not a valid snapshot string
 */
private static ThreadSnapshot parseThreadSnapshot(String snapshot) throws IllegalArgumentException {
  Objects.requireNonNull(snapshot, "snapshot must not be null");

  String[] parts = snapshot.split(";");
  if (parts.length != 3) {
    throw new IllegalArgumentException("Invalid snapshot string");
  }

  String threadName = parts[0];
  String stackTrace = parts[1];
  String threadState = parts[2];

  return new ThreadSnapshot(threadName, stackTrace, threadState);
}

/**
 * Check if a thread snapshot is in any of the given time ranges
 *
 * @param snapshot the thread snapshot
 * @param timeRanges the time ranges to check
 * @return true if the snapshot is in any of the time ranges, false otherwise
 */
private boolean isInTimeRange(ThreadSnapshot snapshot, List<ProfileAnalyzeTimeRange> timeRanges) {
  for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
    long snapshotTimestamp = snapshot.getTimestamp();
    long startTimestamp = timeRange.getStartTimestamp();
    long endTimestamp = timeRange.getEndTimestamp();

    if (snapshotTimestamp >= startTimestamp && snapshotTimestamp <= endTimestamp) {
      return true;
    }
  }

  return false;
}

/**
 * Represents a thread snapshot
