private static class ThreadSnapshot {
  private final String threadName;
  private final String stackTrace;
  private final String threadState;
  private final long timestamp;

  public ThreadSnapshot(String threadName, String stackTrace, String threadState, long timestamp) {
    this.threadName = threadName;
    this.stackTrace = stackTrace;
    this.threadState = threadState;
    this.timestamp = timestamp;
  }

  public String getThreadName() {
    return threadName;
  }

  public String getStackTrace() {
    return stackTrace;
  }

  public String getThreadState() {
    return threadState;
  }

  public long getTimestamp() {
    return timestamp;
  }

  @Override
  public String toString() {
    return "ThreadSnapshot [threadName=" + threadName + ", stackTrace=" + stackTrace + ", threadState=" + threadState + ", timestamp=" + timestamp + "]";
  }
}

