 * Represents a time range for profiling
 */
public static class ProfileAnalyzeTimeRange {
  private final long startTimestamp;
  private final long endTimestamp;

  public ProfileAnalyzeTimeRange(long startTimestamp, long endTimestamp) {
    this.startTimestamp = startTimestamp;
    this.endTimestamp = endTimestamp;
  }

  public long getStartTimestamp() {
    return startTimestamp;
  }

  public long getEndTimestamp() {
    return endTimestamp;
  }

  @Override
  public String toString() {
    return "ProfileAnalyzeTimeRange [startTimestamp=" + startTimestamp + ", endTimestamp=" + endTimestamp + "]";
  }
}

